// Everything downstream needs a stable identifier that survives every
// success and failure branch, created before any API call is made.
const correlationId =
  typeof crypto !== "undefined" && crypto.randomUUID
    ? crypto.randomUUID()
    : `local-${Date.now()}-${Math.random().toString(36).slice(2)}`;

const item = $input.first();
const body = item.json.body || {};
const invoiceFile = item.binary ? item.binary.invoiceFile : undefined;

const demoModeRequested = body.demoMode === "true" || body.demoMode === true;
const submittedOrganizationId =
  typeof body.organizationId === "string" && body.organizationId.trim() !== ""
    ? body.organizationId.trim()
    : null;
// Per the demo plan: default to the fictional org only when the caller
// explicitly opted into demo mode -- never a silent fallback.
const organizationId =
  submittedOrganizationId || (demoModeRequested ? "unternehmen-x-demo" : null);

return [
  {
    json: {
      correlationId,
      receivedAt: new Date().toISOString(),
      hasFile: Boolean(invoiceFile),
      filename: invoiceFile ? invoiceFile.fileName : null,
      mimeType: invoiceFile ? invoiceFile.mimeType : null,
      organizationId,
      demoModeRequested,
    },
    binary: item.binary,
  },
];

// Deterministic 4xx-shaped input/contract checks -- no API call has been
// made yet, so nothing here is a "technical" failure and nothing here is
// ever retried.
const ctx = $input.first().json;

if (!ctx.hasFile) {
  return [{ json: { ...ctx, valid: false, errorCode: "MISSING_INVOICE_FILE", explanation: "No invoiceFile binary field was present in the upload. Not retried: this is an input/contract error, not a service failure." } }];
}
if (!ctx.organizationId) {
  return [{ json: { ...ctx, valid: false, errorCode: "ORGANIZATION_CONTEXT_REQUIRED", explanation: "organizationId was not provided and demoMode was not set. Pass unternehmen-x-demo or unternehmen-y-demo explicitly, or demoMode=true to use Unternehmen X. Not retried: this is an input/contract error, not a service failure." } }];
}
return [{ json: { ...ctx, valid: true } }];

const ctx = $input.first().json;
return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "01.3 Validate upload request",
    errorCode: ctx.errorCode,
    explanation: ctx.explanation,
    invoice: null,
    report: null,
    capabilityInfo: null,
  },
}];

// 02.1 Read API capabilities used options.response.neverError -- a 4xx/5xx HTTP
// response lands here as normal success output (with statusCode/body),
// never as a thrown error. Only a genuine connection-level failure
// (handled by the node's separate error output) is retried.
const ctx = $('01.2 Build run context').item.json;
const resp = $input.first().json;
const statusCode = resp.statusCode;
const body = resp.body || {};

if (statusCode < 200 || statusCode >= 300) {
  return [{
    json: {
      correlationId: ctx.correlationId,
      gateOk: false,
      errorCode: `CAPABILITIES_SERVICE_ERROR_${statusCode}`,
      explanation: `02.1 Read API capabilities returned HTTP ${statusCode}.`,
    },
  }];
}

const facturX = (body.structuredFormats || {})["factur-x"] || {};
const en16931Baseline = (facturX.xsdBaselines || {}).en16931 || {};
const schematron = body.schematron || {};
const processable = Array.isArray(facturX.processableLevels) && facturX.processableLevels.includes("en16931");
const schematronReady = schematron.status === "implemented";

if (!processable || !schematronReady) {
  return [{
    json: {
      correlationId: ctx.correlationId,
      gateOk: false,
      errorCode: "REQUIRED_CAPABILITY_UNAVAILABLE",
      explanation: `EN16931 processable=${processable}, Schematron status=${schematron.status || "unknown"}. This demo requires both.`,
    },
  }];
}

return [{
  json: {
    correlationId: ctx.correlationId,
    gateOk: true,
    capabilityInfo: {
      xsdVersion: en16931Baseline.version,
      legacyBaseline: en16931Baseline.legacyBaseline,
      schematronStatus: schematron.status,
      schematronArtifactVersion: schematron.artifactVersion,
      schematronEngine: schematron.engine,
    },
  },
  binary: $('01.2 Build run context').item.binary,
}];

const ctx = $('01.2 Build run context').item.json;
const ctxErr = $input.first().json;
return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "02.1 Read API capabilities",
    errorCode: "CAPABILITIES_SERVICE_UNAVAILABLE",
    explanation: (ctxErr.error && (ctxErr.error.message || ctxErr.error)) || ctxErr.message || "The capabilities service did not respond after the bounded retry.",
    invoice: null,
    report: null,
    capabilityInfo: null,
  },
}];

const ctx = $input.first().json;
return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "02.2 Evaluate capability gate",
    errorCode: ctx.errorCode,
    explanation: ctx.explanation,
    invoice: null,
    report: null,
    capabilityInfo: null,
  },
}];

// Same neverError contract as 02.1 Read API capabilities: any HTTP response (2xx,
// 4xx, 5xx) lands here as normal output. Only a connection-level failure
// uses the node's error output and gets retried. A 4xx here is therefore
// guaranteed to have been retried zero times.
const ctx = $('01.2 Build run context').item.json;
const resp = $input.first().json;
const statusCode = resp.statusCode;
const body = resp.body || {};

if (statusCode >= 200 && statusCode < 300) {
  const invoice = body.canonicalInvoice.invoice;
  const document = body.canonicalInvoice.document;
  const report = body.phase1ControlReport;
  return [{
    json: {
      correlationId: ctx.correlationId,
      status: report.status,
      routing: report.routing,
      failedStep: null,
      errorCode: null,
      explanation: null,
      invoice,
      document,
      report,
      capabilityInfo: $('02.2 Evaluate capability gate').item.json.capabilityInfo,
    },
  }];
}

const apiDetail = (body.detail && typeof body.detail === "object") ? body.detail : {};
const errorCode = apiDetail.error_code || `HTTP_${statusCode}`;
const explanation = apiDetail.detail || `03.1 Run DigiTax controls returned HTTP ${statusCode}.`;
const retryNote = statusCode >= 400 && statusCode < 500
  ? "Not retried: this is a deterministic input/contract error."
  : "This response was received from the service (not a connection failure), so it was not subject to the connection-level retry either.";

return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "03.1 Run DigiTax controls",
    errorCode,
    explanation: `${explanation} (HTTP ${statusCode}). ${retryNote}`,
    invoice: null,
    report: null,
    capabilityInfo: $('02.2 Evaluate capability gate').item.json.capabilityInfo,
  },
}];

const ctx = $('01.2 Build run context').item.json;
const gate = $('02.2 Evaluate capability gate').item.json;
const ctxErr = $input.first().json;
return [{
  json: {
    correlationId: ctx.correlationId,
    status: "nicht_pruefbar",
    routing: "technical_review",
    failedStep: "03.1 Run DigiTax controls",
    errorCode: "INVOICE_PROCESSING_SERVICE_UNAVAILABLE",
    explanation: (ctxErr.error && (ctxErr.error.message || ctxErr.error)) || ctxErr.message || "The invoice processing service did not respond after the bounded retry.",
    invoice: null,
    report: null,
    capabilityInfo: gate ? gate.capabilityInfo : null,
  },
}];

// Single convergence point for every success and failure branch. Renders
// a self-contained, browser-readable HTML result -- the demo audience
// must never need to inspect raw n8n execution JSON.
const r = $input.first().json;

function esc(s) {
  if (s === null || s === undefined) return "";
  return String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

const statusColors = {
  unauffaellig: "#1b7a3d",
  klaerung_erforderlich: "#a15c00",
  nicht_pruefbar: "#a11616",
};
const statusColor = statusColors[r.status] || "#444";

let body;
if (r.report) {
  const inv = r.invoice;
  const doc = r.document;
  const cap = r.capabilityInfo || {};
  const rows = r.report.controls.map((c) => `
    <tr>
      <td>${esc(c.controlId)}</td>
      <td>${esc(c.outcome)}</td>
      <td>${esc(c.severity)}</td>
      <td>${esc((c.reasonCodes || []).join(", "))}</td>
      <td>${esc(c.message)}</td>
      <td>${esc((c.evidenceRefs || []).join(", "))}</td>
      <td><pre>${esc(c.details ? JSON.stringify(c.details, null, 2) : "")}</pre></td>
    </tr>`).join("");

  body = `
    <h2>Invoice ${esc(inv.invoiceNumber || "(missing)")} dated ${esc(inv.issueDate || "(missing)")}</h2>
    <p><b>Supplier:</b> ${esc(inv.supplier.name)} &rarr; <b>Buyer:</b> ${esc(inv.buyer.name)}</p>
    <p><b>Totals:</b> net ${esc(inv.totals.lineNet)}, tax ${esc(inv.totals.taxAmount)}, gross ${esc(inv.totals.grossAmount)}, payable ${esc(inv.totals.payableAmount)} ${esc(inv.currency)}</p>
    <p><b>Detected format/profile:</b> ${esc(doc.detectedFormat)} / ${esc(doc.profile)}</p>
    <p><b>Validator:</b> Factur-X ${esc(cap.xsdVersion)} EN16931 (legacy baseline: ${esc(cap.legacyBaseline)}) &mdash; Schematron ${esc(cap.schematronStatus)}, artifact ${esc(cap.schematronArtifactVersion)}, engine ${esc(cap.schematronEngine)}</p>
    <p><b>Catalog</b> ${esc(r.report.catalogVersion)} / <b>control profile</b> ${esc(r.report.controlProfileId)} v${esc(r.report.controlProfileVersion)}</p>
    <p><b>Report</b> ${esc(r.report.reportId)} / <b>run</b> ${esc(r.report.runId)} / <b>source SHA-256</b> ${esc(r.report.sourceSha256)}</p>
    <h3>Controls</h3>
    <table border="1" cellpadding="6" cellspacing="0">
      <tr><th>Control</th><th>Outcome</th><th>Severity</th><th>Reason codes</th><th>Message</th><th>Evidence</th><th>Details</th></tr>
      ${rows}
    </table>`;
} else {
  body = `
    <h2>Technical result -- no control report was produced</h2>
    <p><b>Failed step:</b> ${esc(r.failedStep)}</p>
    <p><b>Error code:</b> ${esc(r.errorCode)}</p>
    <p><b>Explanation:</b> ${esc(r.explanation)}</p>`;
}

const html = `<!doctype html>
<html><head><meta charset="utf-8"><title>DigiTax Phase 1 result</title>
<style>
  body { font-family: sans-serif; margin: 2rem; color: #1a1a1a; }
  .banner { padding: 1rem; border-radius: 6px; color: white; background: ${statusColor}; margin-bottom: 1.5rem; }
  table { border-collapse: collapse; width: 100%; }
  th { background: #eee; text-align: left; }
  pre { white-space: pre-wrap; margin: 0; font-size: 0.85em; }
  .boundary { margin-top: 2rem; padding: 1rem; background: #f5f5f5; border-left: 4px solid #888; }
</style>
</head>
<body>
  <div class="banner">
    <b>STATUS: ${esc(r.status)}</b> (routing: ${esc(r.routing)})<br>
    Correlation ID: ${esc(r.correlationId)}
  </div>
  ${body}
  <div class="boundary">
    This is a Phase 1 finding for human review only -- it is not an approval,
    rejection, booking, payment, or supplier communication.
  </div>
</body></html>`;

return [{ json: { ...r, html } }];
